,'address'=>'Địa chỉ','photo'=>'Ảnh sự kiện (đường dẫn uploads/…)'] as $k=>$label):?><label><?=$label?><input name="events[<?=$i?>][<?=$k?>]" type="<?=in_array($k,['date','time'])?$k:'text'?>" value="<?=e($v[$k]??'')?>"></label><?php endforeach;?></div></fieldset><?php endforeach;?><h2>Media & nhạc nền</h2><p class="hint">Dùng đường dẫn HTTPS hoặc đường dẫn uploads/… từ thư mục ảnh đã tải. Mỗi dòng một ảnh.</p><?php foreach(['groom_photo'=>'Ảnh chú rể','bride_photo'=>'Ảnh cô dâu','music'=>'Nhạc nền (URL MP3, không bắt buộc)'] as $k=>$label):?><label><?=$label?><input name="<?=$k?>" value="<?=e($d[$k])?>"></label><?php endforeach;?><?php foreach(['slides'=>'Slider ảnh đầu trang','gallery'=>'Album ảnh'] as $k=>$label):?><label><?=$label?><textarea rows="5" name="<?=$k?>"><?=e(implode("\n",$d[$k]))?></textarea></label><?php endforeach;?><button>Lưu & cập nhật website</button></form></section>
<section id="media" class="panel"><h2>Thư viện ảnh đã tải</h2><p class="hint">Mỗi lượt tối đa 20 ảnh, 8 MB mỗi ảnh và 32 MB tổng. Nhấn vào đường dẫn để sao chép. Chỉ xóa được tệp chưa dùng trên website.</p><form class="media-library-upload" method="post" enctype="multipart/form-data"><?=$csrf?><input type="hidden" name="action" value="upload"><label>Chọn nhiều ảnh<input type="file" name="photos[]" accept="image/jpeg,image/png,image/webp" multiple required></label><button type="submit">Tải ảnh lên</button></form><div class="media-library"><?php foreach(glob(__DIR__.'/uploads/*.{jpg,png,webp}',GLOB_BRACE)?:[] as $file):$path='uploads/'.basename($file);?><article class="media-library-item"><img loading="lazy" src="<?=e($path)?>" alt="Ảnh đã tải lên"><input readonly value="<?=e($path)?>" onclick="this.select()"><form method="post" onsubmit="return confirm('Xóa vĩnh viễn tệp ảnh này?')"><?=$csrf?><input type="hidden" name="action" value="delete_media"><input type="hidden" name="path" value="<?=e($path)?>"><button class="media-delete-button" type="submit">Xóa tệp</button></form></article><?php endforeach;?></div></section>
<section class="panel" id="invitations"><h2>Tạo thiệp mời riêng</h2><p class="hint">Thêm khách để tạo đường dẫn riêng. Mỗi link có QR, điền sẵn tên khách và dùng để theo dõi phản hồi RSVP. Chia sẻ bằng Zalo, Facebook hoặc sao chép link.</p><?php if(!$inviteSchemaReady):?><p role="status">Sổ khách mời chưa kết nối được MySQL.</p><?php else:?><form class="invitee-create" method="post"><?=$csrf?><input type="hidden" name="action" value="save_invitee"><label>Tên khách mời<input name="invitee_name" maxlength="150" placeholder="Ví dụ: Nguyễn Văn An và gia đình" required></label><button type="submit">Tạo thiệp mời</button></form><?php if(!$invitedGuests):?><p>Chưa có khách mời riêng. Tạo khách đầu tiên ở trên.</p><?php else:?><div class="invitee-grid"><?php foreach($invitedGuests as $guest):$inviteUrl=$baseUrl.'/index.php?g='.rawurlencode($guest['token']);$shareUrl=rawurlencode($inviteUrl);$shareQuote=rawurlencode('Trân trọng kính mời bạn đến chung vui cùng Xuân Hiến & Trúc Ly.');?><article class="invitee-card panel"><div class="invitee-info"><div class="invitee-heading"><h3><?=e($guest['name'])?></h3><span class="invitee-status"><?=$guest['attendance']===null?'Chưa phản hồi':($guest['attendance']==='yes'?'Đã xác nhận tham dự':'Đã báo vắng')?></span></div><?php if($guest['attendance']!==null&&$guest['attendance']==='yes'):?><p class="hint">Số người: <?=e($guest['response_guests'])?> · Sự kiện: <?=e($guest['event_name'])?></p><?php endif;?><label>Link thiệp<input readonly value="<?=e($inviteUrl)?>"></label><div class="invitee-actions"><button type="button" class="outline" data-copy-url="<?=e($inviteUrl)?>">Sao chép link</button><a class="btn outline" target="_blank" rel="noopener noreferrer" href="https://zalo.me/share?url=<?=$shareUrl?>">Chia sẻ Zalo</a><a class="btn outline" target="_blank" rel="noopener noreferrer" href="https://www.facebook.com/sharer/sharer.php?u=<?=$shareUrl?>&amp;quote=<?=$shareQuote?>">Chia sẻ Facebook</a><form method="post" onsubmit="return confirm('Thu hồi thiệp mời này? Link và QR sẽ ngừng hoạt động.')"><?=$csrf?><input type="hidden" name="action" value="delete_invitee"><input type="hidden" name="invitee_id" value="<?=e($guest['id'])?>"><button class="invitee-delete" type="submit">Thu hồi</button></form></div><form class="invitee-edit" method="post"><?=$csrf?><input type="hidden" name="action" value="save_invitee"><input type="hidden" name="invitee_id" value="<?=e($guest['id'])?>"><label>Sửa tên khách mời<input name="invitee_name" maxlength="150" value="<?=e($guest['name'])?>" required></label><button type="submit">Lưu tên</button></form></div><aside class="invitee-qr"><div class="qr-image" data-qr-value="<?=e($inviteUrl)?>" role="img" aria-label="Mã QR mở thiệp mời của <?=e($guest['name'])?>"></div><small>Quét mã để mở thiệp</small></aside></article><?php endforeach;?></div><nav class="pagination" aria-label="Phân trang khách mời"><?php if($invitePage>1):?><a href="?ipage=<?=$invitePage-1?>#invitations">Trước</a><?php endif;?><span class="current" aria-current="page"><?=$invitePage?> / <?=$invitePages?></span><?php if($invitePage<$invitePages):?><a href="?ipage=<?=$invitePage+1?>#invitations">Sau</a><?php endif;?></nav><?php endif;?><?php endif;?></section><section id="guests" class="panel"><h2>Khách xác nhận tham dự</h2><p class="hint">Hiển thị 25 phản hồi mỗi trang; số liệu phía trên là tổng lượt phản hồi, không phải số khách duy nhất.</p><div class="table-wrap"><table><thead><tr><th>Khách mời</th><th>Trạng thái</th><th>Số người</th><th>Sự kiện</th><th>Lời nhắn</th><th>Thời gian</th><th>Thao tác</th></tr></thead><tbody><?php foreach($responses as $r):?><tr><td><?=e($r['name'])?></td><td><?=$r['attendance']==='yes'?'Tham dự':'Không dự'?></td><td><?=e($r['guests'])?></td><td><?=e($r['event_name'])?></td><td><?=e($r['note'])?></td><td><?=e($r['created_at'])?></td><td><form method="post" onsubmit="return confirm('Xóa phản hồi này?')"><?=$csrf?><input type="hidden" name="id" value="<?=e($r['id'])?>"><button name="action" value="delete_response">Xóa</button></form></td></tr><?php endforeach;?></tbody></table></div><nav class="pagination" aria-label="Phân trang phản hồi"><?php if($responsePage>1):?><a href="?rpage=<?=$responsePage-1?>&amp;wpage=<?=$wishPage?>#guests">Trước</a><?php endif;?><span class="current" aria-current="page"><?=$responsePage?> / <?=$responsePages?></span><?php if($responsePage<$responsePages):?><a href="?rpage=<?=$responsePage+1?>&amp;wpage=<?=$wishPage?>#guests">Sau</a><?php endif;?></nav><h2>Duyệt lời chúc</h2><div class="table-wrap"><table><thead><tr><th>Khách</th><th>Lời chúc</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($wishes as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['message'])?></td><td><?=$r['approved']?'Công khai':'Chờ duyệt / ẩn'?></td><td><form method="post"><?=$csrf?><input type="hidden" name="id" value="<?=e($r['id'])?>"><button name="action" value="<?=$r['approved']?'hide':'approve'?>"><?=$r['approved']?'Ẩn':'Duyệt'?></button><button name="action" value="delete_wish" onclick="return confirm('Xóa lời chúc này?')">Xóa</button></form></td></tr><?php endforeach;?></tbody></table></div><nav class="pagination" aria-label="Phân trang lời chúc"><?php if($wishPage>1):?><a href="?rpage=<?=$responsePage?>&amp;wpage=<?=$wishPage-1?>#guests">Trước</a><?php endif;?><span class="current" aria-current="page"><?=$wishPage?> / <?=$wishPages?></span><?php if($wishPage<$wishPages):?><a href="?rpage=<?=$responsePage?>&amp;wpage=<?=$wishPage+1?>#guests">Sau</a><?php endif;?></nav></section><section class="panel" id="account"><h2>Đổi mật khẩu</h2><form method="post"><?=$csrf?><input type="hidden" name="action" value="password"><label>Mật khẩu cũ<input name="old" type="password" autocomplete="current-password" required></label><label>Mật khẩu mới<input name="new" type="password" autocomplete="new-password" minlength="12" required></label><button>Đổi mật khẩu</button></form></section></main><?php endif;?></body></html>
